  --muted:#8b978b;
  --font-head:"Bahnschrift","Arial Narrow","Liberation Sans Narrow","DejaVu Sans Condensed",sans-serif;
  --font-body:"Bahnschrift","Segoe UI",system-ui,-apple-system,sans-serif;
  --safe-t:env(safe-area-inset-top,0px);
