input.newString:
.foot-mid{color:#7b8879}
/* ================= OVERLAYS ================= */
.overlay{
  position:absolute;inset:0;z-index:70;display:flex;align-items:center;justify-content:center;
  background:rgba(3,7,7,.72);backdrop-filter:blur(5px) saturate(.8);
  padding:calc(18px + var(--safe-t)) calc(18px + var(--safe-r)) calc(18px + var(--safe-b)) calc(18px + var(--safe-l));
  animation:fadeIn .28s ease;
}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.modal{
  position:relative;width:min(560px,94vw);max-height:92vh;overflow:auto;
  background:linear-gradient(155deg,rgba(20,30,27,.97),rgba(7,12,11,.98));
  border:1px solid rgba(180,196,176,.24);padding:24px 28px 26px;
  box-shadow:0 30px 80px rgba(0,0,0,.6),inset 0 1px 0 rgba(255,255,255,.05);
  clip-path:polygon(16px 0,100% 0,100% calc(100% - 16px),calc(100% - 16px) 100%,0 100%,0 16px);
  animation:modalIn .32s cubic-bezier(.2,.8,.2,1);
}
@keyframes modalIn{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
.modal-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}
.modal-kicker{font-family:var(--font-head);font-size:9px;letter-spacing:.3em;color:var(--amber);font-weight:700}
.close-btn{font-size:22px;line-height:1;color:#849181;width:32px;height:32px;border:1px solid rgba(180,196,176,.18)}
.close-btn:hover{color:var(--amber-2);border-color:var(--amber)}
.modal h2{margin:2px 0 10px;font-family:var(--font-head);font-size:clamp(28px,4.4vw,42px);letter-spacing:.04em;font-weight:800;color:#e6e9d8;text-transform:uppercase;line-height:.98}
.modal-copy{font-size:12.5px;line-height:1.65;color:#a4aea0;margin:0 0 16px}
.help-modal{width:min(780px,96vw)}
.help-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:6px}
.help-col h3{margin:14px 0 6px;font-family:var(--font-head);font-size:9px;letter-spacing:.26em;color:var(--amber)}
.help-col h3:first-child{margin-top:4px}
.help-col p{margin:0 0 9px;font-size:11px;line-height:1.55;color:#a5afa1}
.help-col b{color:#d5dcc8;font-weight:600}
.help-keys{display:flex;flex-wrap:wrap;gap:7px 16px;margin-top:18px;padding-top:14px;border-top:1px solid rgba(180,196,176,.14);font-size:9px;letter-spacing:.08em;color:#7f8c7e}
.help-keys span{display:flex;align-items:center;gap:5px}
kbd{display:inline-grid;place-items:center;min-width:17px;height:17px;padding:0 4px;border:1px solid rgba(180,196,176,.3);background:rgba(255,255,255,.04);font-family:var(--font-head);font-size:8px;color:#cbd3bf}
.pause-modal{width:min(420px,92vw);text-align:center}
.pause-modal h2{margin-bottom:6px}
.pause-actions{display:flex;flex-direction:column;gap:9px;margin-top:20px}
.pause-actions .btn-primary,.pause-actions .btn-ghost{width:100%}
.end-modal{width:min(560px,94vw);text-align:center}
.end-modal h2{font-size:clamp(38px,6vw,62px);letter-spacing:.06em;color:#e9ecd9}
.end-modal.lost h2{color:#e6a094}
.end-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0 22px}
.end-stat{background:rgba(255,255,255,.035);border:1px solid rgba(180,196,176,.14);padding:10px 6px}
.end-stat span{display:block;font-family:var(--font-head);font-size:8px;letter-spacing:.18em;color:#7f8c7e;margin-bottom:4px}
.end-stat b{font-family:var(--font-head);font-size:20px;letter-spacing:.06em;color:#dce2ce;font-weight:700}
.end-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
.end-actions .btn-primary,.end-actions .btn-ghost{min-width:160px}
#rotateNote{display:none}
/* ================= RESPONSIVE ================= */
@media (max-width:900px){
  .start-inner{padding:0 calc(28px + var(--safe-r)) 0 calc(28px + var(--safe-l));gap:18px}
  .start-stats{display:none}
  .start-copy{max-width:620px}
  .start-foot .foot-mid{display:none}
  .tag-loc{display:none}
}
@media (max-width:700px){
  .topbar{height:calc(54px + var(--safe-t));padding:calc(8px + var(--safe-t)) calc(10px + var(--safe-r)) 0 calc(10px + var(--safe-l));gap:8px}
  .tag-kicker{font-size:8px;letter-spacing:.22em}
  .tag-name{font-size:13px;letter-spacing:.1em}
  .threat{height:28px;padding:0 8px;font-size:8.5px;letter-spacing:.14em;gap:6px}
  .threat .clock{margin-left:4px;padding-left:6px;font-size:8px}
  .icon-btn{width:29px;height:29px}
  .icon-btn svg{width:14px;height:14px}
  .top-actions{gap:4px}
  .objectives{top:calc(56px + var(--safe-t));left:calc(10px + var(--safe-l));width:min(214px,52vw);padding:8px 10px 7px}
  .panel-head{font-size:7.5px;padding-bottom:5px;margin-bottom:5px}
  #objectiveList li{font-size:9.5px;gap:6px}
  #objectiveList li .obj-mark{width:9px;height:9px;flex-basis:9px;margin-top:1px}
  #objectiveList li.optional em{display:none}
  .obj-foot{font-size:7px;margin-top:5px;padding-top:5px}
  .minimap-wrap{top:calc(56px + var(--safe-t));right:calc(10px + var(--safe-r));width:106px;padding:5px}
  .mini-head{font-size:6.5px;margin-bottom:3px}
  .mini-scan{display:none}
