      const cx = (x - y) * ISO_X, cy = (x + y + 1) * ISO_Y;
      g.beginPath();
      g.moveTo(cx, cy - ISO_Y - grow); g.lineTo(cx + ISO_X + grow, cy);
      g.lineTo(cx, cy + ISO_Y + grow); g.lineTo(cx - ISO_X - grow, cy);
