  const g = new Float32Array(MAP_W * MAP_H); g.fill(1e9); g[startKey] = 0;
  const f = new Float32Array(MAP_W * MAP_H); f.fill(1e9); f[startKey] = Math.abs(goal.x - start.x) + Math.abs(goal.y - start.y);
