    const prev = i ? rev[i - 1] : start, d = `${Math.sign(rev[i].x - prev.x)},${Math.sign(rev[i].y - prev.y)}`;
    if (d !== lastDir && out.length) out.push(rev[i - 1]);
    lastDir = d;
  }
  if (rev.length) out.push(rev[rev.length - 1]);
