17: const dist = (ax, ay, bx, by) => Math.sqrt(dist2(ax, ay, bx, by));
18: const angleDiff = (a, b) => { let d = (a - b) % TAU; if (d > Math.PI) d -= TAU; if (d < -Math.PI) d += TAU; return d; };
19: const now = () => performance.now() / 1000;
