23:   let h = x * 374761393 + y * 668265263 + seed * 1442695041;
24:   h = (h ^ (h >> 13)) * 1274126177;
25:   h = h ^ (h >> 16);
26:   return ((h >>> 0) % 100000) / 100000;
27: }
28: function mulberry32(a) {
29:   return function () {
30:     a |= 0; a = a + 0x6D2B79F5 | 0;
31:     let t = Math.imul(a ^ a >>> 15, 1 | a);
32:     t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
33:     return ((t ^ t >>> 14) >>> 0) / 4294967296;
