723:         if (!this.world.walkable(nx, ny) || (dx && dy && (!this.world.walkable(x + dx, y) || !this.world.walkable(x, y + dy)))) continue;
724:         const nk = key(nx, ny); if (closed[nk]) continue;
725:         const ng = g[cur] + (dx && dy ? 1.414 : 1);
726:         if (ng >= g[nk]) continue;
727:         came[nk] = cur; g[nk] = ng; f[nk] = ng + Math.hypot(goal.x - nx, goal.y - ny);
728:         if (!open.includes(nk)) open.push(nk);
729:       }
730:     }
731:     if (came[goalKey] < 0) return [{ x: goal.x + .5, y: goal.y + .5 }];
732:     const rev = []; let k = goalKey;
733:     while (k !== startKey && k >= 0) { rev.push({ x: (k % MAP_W) + .5, y: Math.floor(k / MAP_W) + .5 }); k = came[k]; }
