658:     if (Math.hypot(e.clientX - p.sx, e.clientY - p.sy) > 8) p.moved = true;
659:     if (p.pan || p.moved) { p.pan = true; this.camera.x -= dx / this.camera.zoom; this.camera.y -= dy / this.camera.zoom; }
660:     p.x = e.clientX; p.y = e.clientY;
661:   }
662:   pointerUp(e) {
