700:   miniDrag(e) {
701:     const r = this.mini.getBoundingClientRect();
702:     const x = clamp((e.clientX - r.left) / r.width, 0, 1) * MAP_W;
703:     const y = clamp((e.clientY - r.top) / r.height, 0, 1) * MAP_H;
