822:     document.getElementById('endStats').innerHTML = `<span><b>${fmtTime(this.time)}</b><small>TIME</small></span><span><b>${this.kills}</b><small>HOSTILES</small></span><span><b>${alive}/3</b><small>EXTRACTED</small></span>`;
