824:     if (won) audio.play('success'); else audio.play('hurt');
825:   }
826:   killGuard(g, silent = false) {
827:     if (!g?.alive) return;
828:     g.alive = false; g.dead = true; g.mode = 'dead'; this.kills++;
829:     if (!silent) { this.raiseAlarm(0.65); audio.play('shot'); }
