643:     const p = { id: e.pointerId, x: e.clientX, y: e.clientY, sx: e.clientX, sy: e.clientY, moved: false, pan: e.button === 2 || e.button === 1 || e.shiftKey };
644:     if (this.pointer) { this.pointer.pinch = true; this.pointer.second = p; this.pointer.pinchDist = Math.hypot(p.x - this.pointer.x, p.y - this.pointer.y); }
645:     else this.pointer = p;
646:     this.canvas.setPointerCapture(e.pointerId);
647:   }
648:   pointerMove(e) {
649:     const p = this.pointer; if (!p) return;
650:     if (p.second && (p.id === e.pointerId || p.second.id === e.pointerId)) {
651:       const old = p.pinchDist || 1;
652:       if (p.id === e.pointerId) { p.x = e.clientX; p.y = e.clientY; } else { p.second.x = e.clientX; p.second.y = e.clientY; }
653:       const d = Math.hypot(p.second.x - p.x, p.second.y - p.y);
654:       this.camera.zoom = clamp(this.camera.zoom * d / old, 0.48, 1.42); p.pinchDist = d; return;
655:     }
656:     if (p.id !== e.pointerId) return;
657:     const dx = e.clientX - p.x, dy = e.clientY - p.y;
658:     if (Math.hypot(e.clientX - p.sx, e.clientY - p.sy) > 8) p.moved = true;
659:     if (p.pan || p.moved) { p.pan = true; this.camera.x -= dx / this.camera.zoom; this.camera.y -= dy / this.camera.zoom; }
660:     p.x = e.clientX; p.y = e.clientY;
661:   }
662:   pointerUp(e) {
663:     const p = this.pointer; if (!p) return;
664:     if (p.second) {
665:       if (e.pointerId === p.second.id) p.second = null;
666:       else if (e.pointerId === p.id) { Object.assign(p, p.second, { id: p.second.id }); p.second = null; p.sx = p.x; p.sy = p.y; p.pan = false; p.moved = true; }
667:       return;
668:     }
669:     if (e.pointerId !== p.id) return;
670:     if (!p.moved && !p.pan) this.handleTap(e.clientX, e.clientY);
