792:   }
793:   use() {
794:     if (this.state !== 'playing') return;
795:     const unit = this.selectedUnits[0];
796:     if (!unit) return;
797:     const near = (x, y, r = 2.2) => dist(unit.x, unit.y, x, y) <= r;
798:     if (!this.objectives.intel && near(31.3, 14.6, 3.2)) {
