807:     }
808:     if (this.objectives.intel && this.objectives.radio && near(9.5, 4, 3.2)) {
809:       this.objectives.extract = true; this.finish(true); return;
810:     }
811:     this.toast(unit.id !== 'sapper' && !this.objectives.radio && near(this.world.radioTower.x, this.world.radioTower.y, 3) ? 'THE SAPPER MUST PLANT THE CHARGE' : 'NOTHING TO USE HERE');
812:   }
813:   finish(won) {
814:     if (this.state === 'ended') return;
815:     this.state = 'ended';
816:     const alive = this.units.filter(u => u.alive).length;
817:     document.getElementById('endKicker').textContent = won ? 'MISSION COMPLETE' : 'MISSION FAILED';
818:     document.getElementById('endTitle').textContent = won ? 'NIGHTFALL' : 'SQUAD LOST';
819:     document.getElementById('endCopy').textContent = won
820:       ? `The radio tower is silent. The plans are secure. ${alive} commando${alive === 1 ? '' : 's'} made it out${this.objectives.pow ? ', with the prisoner' : ''}.`
821:       : 'The operation is compromised. No commandos remain in the field.';
822:     document.getElementById('endStats').innerHTML = `<span><b>${fmtTime(this.time)}</b><small>TIME</small></span><span><b>${this.kills}</b><small>HOSTILES</small></span><span><b>${alive}/3</b><small>EXTRACTED</small></span>`;
823:     document.getElementById('endScreen').classList.remove('hidden');
824:     if (won) audio.play('success'); else audio.play('hurt');
825:   }
826:   killGuard(g, silent = false) {
