484: /* ============================ DRAWING ============================ */
485: function polygon(ctx, points, fill, stroke = null, width = 1) {
486:   ctx.beginPath();
487:   ctx.moveTo(points[0].x, points[0].y);
488:   for (let i = 1; i < points.length; i++) ctx.lineTo(points[i].x, points[i].y);
489:   ctx.closePath();
490:   if (fill) { ctx.fillStyle = fill; ctx.fill(); }
491:   if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
492: }
493: function drawUnit(ctx, unit, p, selected, time, enemy = false) {
494:   const bob = unit.moving ? Math.sin(time * 13 + unit.phase) * 1.2 : 0;
495:   const scale = enemy ? 1 : 1;
496:   ctx.save();
497:   ctx.translate(p.x, p.y);
498:   ctx.scale(scale, scale);
499:   ctx.fillStyle = 'rgba(0,0,0,.42)';
500:   ctx.beginPath(); ctx.ellipse(0, 0, 8, 3.2, 0, 0, TAU); ctx.fill();
501:   if (selected) {
502:     ctx.strokeStyle = 'rgba(240,190,101,.82)'; ctx.lineWidth = 1.2;
503:     ctx.beginPath(); ctx.ellipse(0, 1, 11, 5, 0, 0, TAU); ctx.stroke();
504:   }
505:   if (unit.dead) {
506:     ctx.rotate(-0.2);
507:     ctx.fillStyle = enemy ? '#62594d' : '#41483e';
508:     ctx.fillRect(-6, -5, 12, 4); ctx.fillStyle = '#b59a79'; ctx.beginPath(); ctx.arc(7, -4, 2.2, 0, TAU); ctx.fill();
509:     ctx.restore(); return;
510:   }
511:   const body = enemy ? '#766b51' : unit.color;
512:   ctx.fillStyle = body;
513:   ctx.beginPath(); ctx.ellipse(0, -8 + bob, 4.8, 7.3, unit.facing, 0, TAU); ctx.fill();
514:   ctx.fillStyle = enemy ? '#c1ab82' : '#b5a27c';
515:   ctx.beginPath(); ctx.arc(0, -15 + bob, 3.1, 0, TAU); ctx.fill();
516:   ctx.fillStyle = enemy ? '#39362e' : '#2d352e';
517:   ctx.beginPath(); ctx.ellipse(0, -17 + bob, 4, 2.1, 0, Math.PI, TAU); ctx.fill();
518:   ctx.strokeStyle = '#252b26'; ctx.lineWidth = 2;
519:   ctx.beginPath(); ctx.moveTo(2, -9 + bob); ctx.lineTo(9, -11 + bob); ctx.stroke();
520:   if (unit.crouch && !enemy) {
521:     ctx.fillStyle = 'rgba(122,164,103,.48)'; ctx.beginPath(); ctx.arc(-3, -7, 8, 0, TAU); ctx.fill();
522:   }
523:   if (unit.health < 100) {
524:     ctx.fillStyle = 'rgba(0,0,0,.65)'; ctx.fillRect(-8, -24, 16, 2);
525:     ctx.fillStyle = unit.health > 40 ? '#a4bf73' : '#d25843'; ctx.fillRect(-8, -24, 16 * unit.health / 100, 2);
526:   }
527:   ctx.restore();
528: }
