316:     this.objects.push({ type: 'extraction', x: 9.5, y: 4.0, depth: 9.5 + 4.0 });
317:     // dinghy at insertion
318:     this.objects.push({ type: 'dinghy', x: 10.2, y: 48.1, depth: 10.2 + 48.1 });
319:     // wreck / flavour
320:     this.objects.push({ type: 'wreck', x: 18.2, y: 42.4, depth: 18.2 + 42.4 });
321:     this.objects.push({ type: 'sign', x: 31.6, y: 30.2, depth: 31.6 + 30.2, text: 'CHECKPOINT 7' });
322:     // sort static objects by depth for first draw; units inserted each frame
323:     this.objects.sort((a, b) => a.depth - b.depth);
324:   }
325:   road(points, width, type = T.ROAD) {
326:     for (let i = 0; i < points.length - 1; i++) {
327:       const [x0, y0] = points[i], [x1, y1] = points[i + 1];
328:       const len = Math.hypot(x1 - x0, y1 - y0);
329:       const steps = Math.ceil(len / 0.25);
330:       for (let s = 0; s <= steps; s++) {
331:         const t = s / steps, cx = lerp(x0, x1, t), cy = lerp(y0, y1, t);
332:         const r = width / 2;
333:         for (let y = Math.floor(cy - r - 1); y <= Math.ceil(cy + r + 1); y++) {
334:           for (let x = Math.floor(cx - r - 1); x <= Math.ceil(cx + r + 1); x++) {
335:             const dx = x + 0.5 - cx, dy = y + 0.5 - cy;
336:             if (dx * dx + dy * dy <= r * r) {
337:               if (this.get(x, y) !== T.WATER) this.set(x, y, type);
338:             }
339:           }
340:         }
341:       }
342:     }
343:   }
344:   fence(x, y) {
345:     this.set(x, y, T.FENCE);
346:     this.fences.push({ x: x + 0.5, y: y + 0.5, depth: x + y + 1 });
347:   }
348:   addBuilding(b) {
349:     b.type = 'building';
350:     b.depth = b.x + b.y + b.w + b.h;
351:     for (let y = Math.floor(b.y); y < Math.ceil(b.y + b.h); y++) {
352:       for (let x = Math.floor(b.x); x < Math.ceil(b.x + b.w); x++) {
353:         this.block(x, y);
354:         if (this.get(x, y) !== T.WATER) this.set(x, y, T.CONCRETE);
355:       }
356:     }
357:     this.buildings.push(b);
358:     this.objects.push(b);
359:   }
360:   addTower(x, y, side) {
361:     this.block(Math.floor(x), Math.floor(y));
362:     const obj = { type: 'watchtower', x, y, depth: x + y + 0.5, side };
363:     this.objects.push(obj);
364:     const sl = {
365:       type: 'searchlight', x, y, z: 3.7, base: side === 'west' ? 0.72 : -2.35,
366:       sweep: side === 'west' ? 0.95 : 0.85, speed: side === 'west' ? 0.34 : 0.28,
367:       phase: side === 'west' ? 0.4 : 2.1, range: 13.5, half: 0.15, angle: 0
368:     };
369:     this.searchlights.push(sl);
370:   }
371:   addRadioTower(x, y) {
372:     this.block(Math.floor(x), Math.floor(y));
373:     this.block(Math.floor(x) + 1, Math.floor(y));
374:     const obj = { type: 'radiotower', x, y, depth: x + y + 1.5, destroyed: false, collapse: 0 };
375:     this.objects.push(obj);
376:     this.radioTower = obj;
377:     this.lights.push({ type: 'beacon', x, y, z: 5.4, radius: 2.6, color: [255, 58, 42], intensity: 0.4, phase: 0 });
378:   }
379:   renderTerrain() {
380:     const margin = 190;
381:     const minX = -MAP_H * ISO_X - margin;
382:     const minY = -margin;
383:     const cw = (MAP_W + MAP_H) * ISO_X + margin * 2;
384:     const ch = (MAP_W + MAP_H) * ISO_Y + margin * 2;
385:     const c = document.createElement('canvas');
386:     c.width = cw; c.height = ch;
387:     const g = c.getContext('2d');
388:     g.translate(-minX, -minY);
389:     g.fillStyle = '#071011'; g.fillRect(minX, minY, cw, ch);
390:     const diamond = (x, y, grow = 0) => {
391:       const cx = (x - y) * ISO_X, cy = (x + y + 1) * ISO_Y;
392:       g.beginPath();
393:       g.moveTo(cx, cy - ISO_Y - grow); g.lineTo(cx + ISO_X + grow, cy);
394:       g.lineTo(cx, cy + ISO_Y + grow); g.lineTo(cx - ISO_X - grow, cy);
395:       g.closePath();
396:       return { cx, cy };
397:     };
398:     for (let y = 0; y < MAP_H; y++) {
399:       for (let x = 0; x < MAP_W; x++) {
400:         const t = this.get(x, y);
401:         const n = hash2(x, y, 7);
402:         let base;
403:         if (t === T.WATER) base = n < .5 ? '#18323b' : '#1a3740';
404:         else if (t === T.SAND) base = n < .5 ? '#7d7152' : '#877a58';
405:         else if (t === T.GRASS) base = n < .5 ? '#39452f' : '#3f4b34';
406:         else if (t === T.ROAD) base = n < .5 ? '#5d513d' : '#665943';
407:         else if (t === T.CONCRETE) base = n < .5 ? '#50544d' : '#565a52';
408:         else if (t === T.ROCK) base = n < .5 ? '#46453e' : '#4d4b43';
409:         else if (t === T.BUSH) base = '#35412d';
410:         else if (t === T.TREE) base = '#33402d';
411:         else if (t === T.FENCE) base = '#39452f';
412:         else base = '#39452f';
413:         const p = diamond(x, y, 0.4);
414:         g.fillStyle = base; g.fill();
415:         // fine grain texture
416:         if (t === T.GRASS || t === T.BUSH || t === T.TREE) {
417:           const cnt = 2 + Math.floor(n * 3);
418:           for (let i = 0; i < cnt; i++) {
419:             const a = hash2(x * 7 + i, y * 11, 3), b = hash2(x * 5, y * 13 + i, 9);
420:             const px = p.cx + (a - .5) * 44, py = p.cy + (b - .5) * 20;
421:             g.strokeStyle = i % 2 ? 'rgba(126,143,96,.34)' : 'rgba(26,36,24,.4)';
422:             g.lineWidth = .7; g.beginPath(); g.moveTo(px, py); g.lineTo(px + (a - .5) * 3, py - 2.2 - b * 2.5); g.stroke();
423:           }
424:         } else if (t === T.SAND) {
425:           for (let i = 0; i < 3; i++) {
426:             const a = hash2(x * 9 + i, y * 3, 5), b = hash2(x * 3, y * 9 + i, 6);
427:             g.fillStyle = i % 2 ? 'rgba(196,180,136,.18)' : 'rgba(56,48,34,.22)';
428:             g.fillRect(p.cx + (a - .5) * 46, p.cy + (b - .5) * 18, 1.2, 1.2);
429:           }
430:         } else if (t === T.ROAD) {
431:           g.strokeStyle = 'rgba(45,39,28,.3)'; g.lineWidth = .8;
432:           const a = hash2(x, y, 21);
433:           g.beginPath(); g.moveTo(p.cx - 20 + a * 12, p.cy + 3); g.lineTo(p.cx + 16 - a * 9, p.cy - 4); g.stroke();
434:           if (n > .7) { g.fillStyle = 'rgba(160,148,115,.13)'; g.fillRect(p.cx - 8, p.cy - 2, 2, 1); }
435:         } else if (t === T.CONCRETE) {
436:           g.strokeStyle = 'rgba(30,32,29,.35)'; g.lineWidth = .7;
437:           if (x % 3 === 0) { g.beginPath(); g.moveTo(p.cx - 20, p.cy - 4); g.lineTo(p.cx + 18, p.cy + 4); g.stroke(); }
438:           if (n > .78) { g.strokeStyle = 'rgba(28,30,27,.5)'; g.beginPath(); g.moveTo(p.cx - 10, p.cy + 2); g.lineTo(p.cx - 2, p.cy - 3); g.lineTo(p.cx + 5, p.cy - 1); g.stroke(); }
439:         } else if (t === T.WATER) {
440:           const a = hash2(x, y, 31);
441:           g.strokeStyle = 'rgba(104,150,153,.2)'; g.lineWidth = .8;
442:           g.beginPath();
443:           g.moveTo(p.cx - 16 + a * 8, p.cy - 2);
444:           g.quadraticCurveTo(p.cx - 4 + a * 8, p.cy - 6, p.cx + 8 + a * 8, p.cy - 2);
445:           g.stroke();
446:           if (n > .55) { g.strokeStyle = 'rgba(160,194,190,.13)'; g.beginPath(); g.moveTo(p.cx - 8, p.cy + 6); g.lineTo(p.cx + 2, p.cy + 4); g.stroke(); }
447:         }
448:       }
449:     }
450:     // shore foam
451:     for (const [x, y] of this.waterTiles) {
452:       const cx = (x - y) * ISO_X, cy = (x + y + 1) * ISO_Y;
453:       const north = this.get(x, y - 1), west = this.get(x - 1, y);
454:       if (north === T.SAND) {
455:         g.strokeStyle = 'rgba(207,214,190,.38)'; g.lineWidth = 1.6;
456:         g.beginPath(); g.moveTo(cx, cy - ISO_Y + 1); g.lineTo(cx + ISO_X - 2, cy); g.stroke();
457:         g.strokeStyle = 'rgba(207,214,190,.12)'; g.lineWidth = 4;
458:         g.beginPath(); g.moveTo(cx, cy - ISO_Y + 5); g.lineTo(cx + ISO_X - 5, cy + 3); g.stroke();
459:       }
460:       if (west === T.SAND) {
461:         g.strokeStyle = 'rgba(207,214,190,.38)'; g.lineWidth = 1.6;
462:         g.beginPath(); g.moveTo(cx - ISO_X + 2, cy); g.lineTo(cx, cy - ISO_Y + 1); g.stroke();
463:         g.strokeStyle = 'rgba(207,214,190,.12)'; g.lineWidth = 4;
464:         g.beginPath(); g.moveTo(cx - ISO_X + 5, cy + 3); g.lineTo(cx, cy - ISO_Y + 5); g.stroke();
465:       }
466:     }
467:     // broad ground variation
468:     const R = mulberry32(77);
469:     for (let i = 0; i < 240; i++) {
470:       const wx = R() * MAP_W, wy = R() * MAP_H;
471:       if (this.get(Math.floor(wx), Math.floor(wy)) === T.WATER) continue;
472:       const p = iso(wx, wy);
473:       g.fillStyle = i % 3 === 0 ? 'rgba(20,28,18,.055)' : i % 3 === 1 ? 'rgba(170,158,118,.045)' : 'rgba(80,96,62,.05)';
474:       g.beginPath(); g.ellipse(p.x, p.y, 12 + R() * 38, 6 + R() * 18, R() * 3, 0, TAU); g.fill();
475:     }
476:     // map edge
477:     const edge = [[0, 0], [MAP_W, 0], [MAP_W, MAP_H], [0, MAP_H]].map(([x, y]) => iso(x, y));
478:     g.strokeStyle = 'rgba(0,0,0,.6)'; g.lineWidth = 20;
479:     g.beginPath(); g.moveTo(edge[0].x, edge[0].y); for (let i = 1; i < 4; i++) g.lineTo(edge[i].x, edge[i].y); g.closePath(); g.stroke();
480:     return { canvas: c, minX, minY, w: cw, h: ch };
481:   }
482: }
