681:   }
682:   handleTap(sx, sy) {
683:     if (this.state !== 'playing') return;
684:     const w = this.screenToWorld(sx, sy);
685:     const hit = (arr, radius) => arr.find(o => o.alive && !o.dead && dist2(w.x, w.y, o.x, o.y) < radius * radius);
686:     const guard = hit(this.guards, 0.85);
687:     if (guard) { this.attack(guard); return; }
688:     const friend = this.units.findIndex(u => u.alive && dist2(w.x, w.y, u.x, u.y) < 0.72 * 0.72);
689:     if (friend >= 0) { this.selectUnit(friend); return; }
690:     if (this.grenadeArmed) {
691:       this.grenadeArmed = false; document.getElementById('btnGrenade').classList.remove('armed');
692:       this.throwGrenade(w.x, w.y); return;
693:     }
694:     const target = nearestWalkable(this.world, w.x, w.y);
695:     if (this.selectAll) {
696:       const offsets = [[-0.8, -0.5], [0.8, 0], [0, 0.9]];
697:       this.units.forEach((u, i) => { if (!u.alive) return; this.commandMove(u, target.x + offsets[i][0], target.y + offsets[i][1]); });
698:     } else this.selectedUnits.forEach(u => this.commandMove(u, target.x + 0.5, target.y + 0.5));
699:   }
700:   miniDrag(e) {
701:     const r = this.mini.getBoundingClientRect();
702:     const x = clamp((e.clientX - r.left) / r.width, 0, 1) * MAP_W;
703:     const y = clamp((e.clientY - r.top) / r.height, 0, 1) * MAP_H;
