438:           if (n > .78) { g.strokeStyle = 'rgba(28,30,27,.5)'; g.beginPath(); g.moveTo(p.cx - 10, p.cy + 2); g.lineTo(p.cx - 2, p.cy - 3); g.lineTo(p.cx + 5, p.cy - 1); g.stroke(); }
439:         } else if (t === T.WATER) {
440:           const a = hash2(x, y, 31);
441:           g.strokeStyle = 'rgba(104,150,153,.2)'; g.lineWidth = .8;
442:           g.beginPath();
443:           g.moveTo(p.cx - 16 + a * 8, p.cy - 2);
444:           g.quadraticCurveTo(p.cx - 4 + a * 8, p.cy - 6, p.cx + 8 + a * 8, p.cy - 2);
445:           g.stroke();
446:           if (n > .55) { g.strokeStyle = 'rgba(160,194,190,.13)'; g.beginPath(); g.moveTo(p.cx - 8, p.cy + 6); g.lineTo(p.cx + 2, p.cy + 4); g.stroke(); }
447:         }
448:       }
449:     }
450:     // shore foam
451:     for (const [x, y] of this.waterTiles) {
