479:     g.beginPath(); g.moveTo(edge[0].x, edge[0].y); for (let i = 1; i < 4; i++) g.lineTo(edge[i].x, edge[i].y); g.closePath(); g.stroke();
480:     return { canvas: c, minX, minY, w: cw, h: ch };
481:   }
