725:         const ng = g[cur] + (dx && dy ? 1.414 : 1);
726:         if (ng >= g[nk]) continue;
727:         came[nk] = cur; g[nk] = ng; f[nk] = ng + Math.hypot(goal.x - nx, goal.y - ny);
728:         if (!open.includes(nk)) open.push(nk);
