770:   knife(target = null) {
771:     const unit = this.selectedUnits[0]; if (!unit) return;
772:     const enemy = target || this.guards.filter(g => g.alive).sort((a,b)=>dist2(unit.x,unit.y,a.x,a.y)-dist2(unit.x,unit.y,b.x,b.y))[0];
