890:     u.health = Math.max(0, u.health - amount);
891:     if (u.health === 0) { u.alive = false; u.dead = true; this.casualties++; u.moving = false; u.path = []; this.renderCards(); audio.play('hurt'); this.toast(`${u.role} DOWN`); }
