918:       if (g.mode === 'hunt') {
919:         const target = this.units.filter(u => u.alive).sort((a,b)=>dist2(g.x,g.y,a.x,a.y)-dist2(g.x,g.y,b.x,b.y))[0];
920:         if (target && dist(g.x,g.y,target.x,target.y) < 8 && g.cooldown <= 0) {
921:           g.cooldown = 1.5; target.facing = Math.atan2(g.y-target.y,g.x-target.x); this.hurtUnit(target, 13); audio.play('shot', { pan: clamp((g.x-28)/28,-1,1) });
922:         }
923:       }
924:     }
925:   }
