650:     if (p.second && (p.id === e.pointerId || p.second.id === e.pointerId)) {
651:       const old = p.pinchDist || 1;
652:       if (p.id === e.pointerId) { p.x = e.clientX; p.y = e.clientY; } else { p.second.x = e.clientX; p.second.y = e.clientY; }
653:       const d = Math.hypot(p.second.x - p.x, p.second.y - p.y);
