870:       }
871:     }
872:     this.effects = this.effects.filter(fx => fx.type === 'grenade' || this.time < fx.until);
873:     if (this.interacting?.type === 'radio') {
874:       const it = this.interacting;
875:       if (!it.unit.alive || dist(it.unit.x, it.unit.y, this.world.radioTower.x, this.world.radioTower.y) > 3.2) { this.interacting = null; this.toast('CHARGE PLANTING INTERRUPTED'); }
876:       else if ((it.progress += dt) >= 3.2) {
877:         this.objectives.radio = true; this.interacting = null; this.world.radioTower.destroyed = true;
878:         this.effects.push({ type: 'blast', x: this.world.radioTower.x, y: this.world.radioTower.y, born: this.time, until: this.time + 1.2 });
879:         audio.play('explosion'); this.raiseAlarm(0.45); this.toast('RADIO TOWER DESTROYED'); this.updateHUD();
880:       }
881:     }
882:     const search = this.world.searchlights;
883:     for (const sl of search) sl.angle = sl.base + Math.sin(this.time * sl.speed + sl.phase) * sl.sweep;
