885:     if (this.time - this.lastMinimap > 0.25) { this.drawMinimap(); this.lastMinimap = this.time; }
886:     this.updateHUD();
887:   }
888:   hurtUnit(u, amount) {
889:     if (!u.alive) return;
890:     u.health = Math.max(0, u.health - amount);
891:     if (u.health === 0) { u.alive = false; u.dead = true; this.casualties++; u.moving = false; u.path = []; this.renderCards(); audio.play('hurt'); this.toast(`${u.role} DOWN`); }
892:   }
893:   updateGuards(dt) {
894:     for (const g of this.guards) {
895:       if (!g.alive) continue;
896:       g.cooldown = Math.max(0, g.cooldown - dt);
897:       if (g.mode === 'patrol' && g.kind === 'patrol' && !g.path.length) {
898:         g.waypoint = (g.waypoint + 1) % g.waypoints.length;
899:         const w = g.waypoints[g.waypoint]; g.path = this.pathfind(g.x, g.y, w[0], w[1]);
900:       }
901:       if (g.path.length) {
902:         const p = g.path[0], dx = p.x - g.x, dy = p.y - g.y, d = Math.hypot(dx, dy);
903:         if (d < 0.12) g.path.shift(); else { const step = Math.min(d, (g.mode === 'hunt' ? 1.75 : 0.72) * dt); g.x += dx / d * step; g.y += dy / d * step; g.facing = Math.atan2(dy, dx); }
904:       }
905:       let seen = null, best = Infinity;
906:       for (const u of this.units) {
907:         if (!u.alive) continue;
908:         const d = dist(g.x, g.y, u.x, u.y); if (d > 9.5) continue;
909:         const a = Math.atan2(u.y - g.y, u.x - g.x);
910:         if (Math.abs(angleDiff(a, g.facing)) > (u.crouch ? 0.62 : 0.86)) continue;
911:         if (d < best) { best = d; seen = u; }
912:       }
913:       if (seen) {
914:         g.suspicion = clamp(g.suspicion + dt * (seen.crouch ? 0.19 : 0.38) * (best < 4 ? 1.7 : 1), 0, 1);
915:         if (g.suspicion > 0.48) g.mode = 'suspicious';
916:         if (g.suspicion >= 1) { g.mode = 'hunt'; g.path = this.pathfind(g.x, g.y, seen.x, seen.y); this.raiseAlarm(0.8); }
917:       } else g.suspicion = Math.max(0, g.suspicion - dt * 0.12);
918:       if (g.mode === 'hunt') {
919:         const target = this.units.filter(u => u.alive).sort((a,b)=>dist2(g.x,g.y,a.x,a.y)-dist2(g.x,g.y,b.x,b.y))[0];
920:         if (target && dist(g.x,g.y,target.x,target.y) < 8 && g.cooldown <= 0) {
921:           g.cooldown = 1.5; target.facing = Math.atan2(g.y-target.y,g.x-target.x); this.hurtUnit(target, 13); audio.play('shot', { pan: clamp((g.x-28)/28,-1,1) });
922:         }
923:       }
924:     }
925:   }
