673:   screenToWorld(sx, sy) {
674:     const { w, h } = this.size, ix = (sx - w / 2) / this.camera.zoom + this.camera.x;
675:     const iy = (sy - h / 2) / this.camera.zoom + this.camera.y;
676:     return { x: (ix / ISO_X + iy / ISO_Y) / 2, y: (iy / ISO_Y - ix / ISO_X) / 2 };
677:   }
678:   worldToScreen(x, y, z = 0) {
679:     const p = iso(x, y, z);
