838:     this.time += dt;
839:     if (this.toastTimer > 0) { this.toastTimer -= dt; if (this.toastTimer <= 0) this.toastEl.classList.remove('show'); }
840:     for (const u of this.units) {
841:       if (!u.alive) continue;
842:       u.cooldown = Math.max(0, u.cooldown - dt);
843:       if (u.target?.alive) {
844:         const d = dist(u.x, u.y, u.target.x, u.target.y);
845:         if (d > u.range * 0.82) this.commandMove(u, u.target.x, u.target.y);
846:         else if (u.cooldown <= 0) {
847:           u.facing = Math.atan2(u.target.y - u.y, u.target.x - u.x);
848:           u.cooldown = u.rate; u.target.health -= u.weapon === 'rifle' ? 65 : 42;
849:           audio.play(u.weapon, { pan: clamp((u.x - 28) / 28, -1, 1) });
850:           this.raiseAlarm(u.weapon === 'silenced' ? 0.035 : 0.24);
851:           if (u.target.health <= 0) this.killGuard(u.target, false);
852:         }
853:       }
854:       if (u.moving && u.path.length) {
