530: /* ============================ GAME ============================ */
531: const UNIT_DEFS = [
532:   { id: 'scout', name: 'JACK O’HARA', role: 'GREEN BERET', color: '#66764a', weapon: 'silenced', speed: 2.65, range: 8.5, rate: 1.05 },
533:   { id: 'sniper', name: 'FRANCIS T. WOOLRIDGE', role: 'SNIPER', color: '#61705a', weapon: 'rifle', speed: 2.35, range: 15, rate: 2.3 },
534:   { id: 'sapper', name: 'SAMUEL BROOKLYN', role: 'SAPPER', color: '#79734c', weapon: 'shot', speed: 2.3, range: 8, rate: 1.4 }
